fn main() {
    let a = [1, 2, 3];
    let b = ['x', 'y'];
    let n = a.iter().zip(b.iter()).count();
    println!("{n}");
}

fn main() {
    let v = vec!["a", "bb", "ccc", "dddd"];
    let r = v
        .iter()
        .enumerate()
        .filter(|(i, _)| i % 2 == 1)
        .map(|(_, s)| s.len())
        .fold(0, |acc, n| acc * 10 + n);
    println!("{r}");
}
